gc1(){return"\u092a\u094d\u0930\u0938\u094d\u0924\u0941\u0924\u093f \u0915\u0940 \u0938\u0942\u091a\u0940 \u092c\u0928\u093e\u090f\u0901, \u0915\u0920\u093f\u0928 \u0905\u0902\u0936 \u0926\u094b\u0939\u0930\u093e\u090f\u0901 \u0914\u0930 \u092a\u0928\u094d\u0928\u094b\u0902 \u0915\u094b \u0915\u094d\u0930\u092e \u092e\u0947\u0902 \u0930\u0916\u0947\u0902\u0964"},
gd2(){return"\u0905\u092a\u0928\u0940 \u0930\u091a\u0928\u093e \u0915\u093e \u0916\u093c\u092f\u093e\u0932 \u0930\u0916\u0947\u0902"},
gd6(){return"\u0935\u093f\u091a\u093e\u0930 \u092c\u0926\u0932 \u0938\u0915\u0924\u0947 \u0939\u0948\u0902\u0964\n\u092e\u0942\u0932 \u0938\u0941\u0930\u0915\u094d\u0937\u093f\u0924 \u0930\u0939\u0928\u093e \u091a\u093e\u0939\u093f\u090f\u0964"},
gd1(){return"\u091f\u093f\u092a\u094d\u092a\u0923\u093f\u092f\u093e\u0901 \u0914\u0930 \u092a\u0922\u093c\u0928\u0947 \u0915\u0947 \u0926\u0943\u0936\u094d\u092f \u092e\u0947\u0902 \u092c\u0926\u0932\u093e\u0935 \u092e\u0942\u0932 PDF \u0915\u094b \u0938\u0941\u0930\u0915\u094d\u0937\u093f\u0924 \u0930\u0916\u0924\u0947 \u0939\u0948\u0902\u0964 \u0932\u093e\u0907\u092c\u094d\u0930\u0947\u0930\u0940 \u0909\u092a\u0915\u0930\u0923 \u092a\u0930 \u0938\u094d\u0925\u093e\u0928\u0940\u092f \u0930\u0942\u092a \u0938\u0947 \u0938\u0939\u0947\u091c\u0940 \u091c\u093e\u0924\u0940 \u0939\u0948; \u0928\u093f\u0930\u094d\u092f\u093e\u0924 \u0914\u0930 \u092c\u0948\u0915\u0905\u092a \u0906\u092a\u0915\u0947 \u0928\u093f\u092f\u0902\u0924\u094d\u0930\u0923 \u092e\u0947\u0902 \u0939\u0948\u0902\u0964 \u0921\u0947\u091f\u093e \u0924\u092d\u0940 \u092d\u0947\u091c\u093e \u091c\u093e\u0924\u093e \u0939\u0948 \u091c\u092c \u0906\u092a \u0915\u094b\u0908 \u0938\u0947\u0935\u093e \u091c\u094b\u0921\u093c\u0915\u0930 \u0938\u094d\u092a\u0937\u094d\u091f \u0930\u0942\u092a \u0938\u0947 \u0915\u094b\u0908 \u092a\u094d\u0930\u0915\u094d\u0930\u093f\u092f\u093e \u0936\u0941\u0930\u0942 \u0915\u0930\u0924\u0947 \u0939\u0948\u0902\u0964 \u0905\u092a\u0928\u0947 \u0906\u092a \u0915\u094d\u0932\u093e\u0909\u0921 \u0938\u093f\u0902\u0915 \u0915\u0940 \u0938\u0941\u0935\u093f\u0927\u093e \u0909\u092a\u0932\u092c\u094d\u0927 \u0928\u0939\u0940\u0902 \u0939\u0948\u0964"},
