gcM(){return"\u0938\u0902\u0917\u0940\u0924 \u0915\u0947 \u0932\u093f\u090f \u0925\u094b\u0921\u093c\u0940 \u0914\u0930 \u091c\u0917\u0939\u0964"},
gcL(){return"\xa9 2026 CantaVue"},
gcN(){return"\u092a\u0902\u091c\u0940\u0915\u0930\u0923 \u092f\u093e \u0938\u0926\u0938\u094d\u092f\u0924\u093e \u0915\u0947 \u092b\u093c\u0949\u0930\u094d\u092e \u0928\u0939\u0940\u0902 \u0939\u0948\u0902\u0964 \u0939\u094b\u0938\u094d\u091f\u093f\u0902\u0917 \u092e\u0947\u0902 \u092c\u0941\u0928\u093f\u092f\u093e\u0926\u0940 \u0935\u093f\u091c\u093c\u093f\u091f \u0906\u0901\u0915\u0921\u093c\u0947 \u0936\u093e\u092e\u093f\u0932 \u0939\u0948\u0902; \u0939\u092e\u093e\u0930\u0940 \u0917\u094b\u092a\u0928\u0940\u092f\u0924\u093e \u0928\u0940\u0924\u093f \u0926\u0947\u0916\u0947\u0902\u0964"},
gcg(){return"\u0935\u093e\u092f\u0932\u093f\u0928 \u0915\u0940 \u0915\u0915\u094d\u0937\u093e\u090f\u0901"},
gci(){return"\u0938\u0902\u0917\u0940\u0924 \u0935\u093e\u0915\u094d\u092f \u0938\u093f\u0916\u093e\u090f\u0901\u0964 \u092a\u0932 \u0915\u094b \u091a\u093f\u0939\u094d\u0928\u093f\u0924 \u0915\u0930\u0947\u0902\u0964"},
gcf(){return"\u0917\u091c \u091a\u0932\u093e\u0928\u0947 \u0915\u0940 \u0926\u093f\u0936\u093e, \u0909\u0901\u0917\u0932\u093f\u092f\u094b\u0902 \u0915\u093e \u0915\u094d\u0930\u092e \u0914\u0930 \u0938\u0902\u0917\u0940\u0924 \u0935\u093e\u0915\u094d\u092f \u0915\u093e \u0935\u093f\u0928\u094d\u092f\u093e\u0938 \u0938\u0940\u0927\u0947 \u0938\u094d\u0935\u0930\u0932\u093f\u092a\u093f \u092a\u0930 \u0932\u093f\u0916\u0947\u0902, \u0924\u093e\u0915\u093f \u092a\u094d\u0930\u0926\u0930\u094d\u0936\u0928 \u0914\u0930 \u091a\u0930\u094d\u091a\u093e \u090f\u0915 \u0939\u0940 \u092a\u0928\u094d\u0928\u0947 \u092a\u0930 \u0930\u0939\u0947\u0902\u0964"},
gce(){return"\u090f\u0915 \u0935\u093e\u092f\u0932\u093f\u0928 \u0936\u093f\u0915\u094d\u0937\u0915 \u0914\u0930 \u0935\u092f\u0938\u094d\u0915 \u0935\u093f\u0926\u094d\u092f\u093e\u0930\u094d\u0925\u0940 \u0938\u0902\u0917\u0940\u0924 \u0938\u094d\u091f\u0942\u0921\u093f\u092f\u094b \u092e\u0947\u0902 \u091f\u0948\u092c\u0932\u0947\u091f \u0915\u0940 \u0938\u094d\u0935\u0930\u0932\u093f\u092a\u093f \u0938\u093e\u0925 \u0926\u0947\u0916 \u0930\u0939\u0947 \u0939\u0948\u0902\u0964 \u0936\u093f\u0915\u094d\u0937\u0915 \u0938\u094d\u091f\u093e\u0907\u0932\u0938 \u0938\u0947 \u0907\u0936\u093e\u0930\u093e \u0915\u0930 \u0930\u0939\u0947 \u0939\u0948\u0902\u0964"},
gcb(){return"\u0938\u092e\u0942\u0939 \u0935\u093e\u0926\u0928"},
gcc(){return"\u0939\u0930 \u0924\u0948\u092f\u093e\u0930 \u092a\u0928\u094d\u0928\u093e \u092e\u0902\u091a \u0924\u0915 \u0932\u0947 \u091c\u093e\u090f\u0901\u0964"},
gca(){return"\u092e\u0902\u091a \u092a\u0930 \u091c\u093e\u0928\u0947 \u0938\u0947 \u092a\u0939\u0932\u0947 \u092a\u094d\u0930\u0938\u094d\u0924\u0941\u0924\u093f \u0915\u0940 \u0938\u0942\u091a\u0940 \u0914\u0930 \u0905\u092a\u0928\u0940 \u0938\u094d\u0935\u0930\u0932\u093f\u092a\u093f\u092f\u093e\u0901 \u0924\u0948\u092f\u093e\u0930 \u0915\u0930\u0947\u0902, \u0924\u093e\u0915\u093f \u0906\u0938\u092a\u093e\u0938 \u0915\u0947 \u0938\u0902\u0917\u0940\u0924 \u092a\u0930 \u0905\u0927\u093f\u0915 \u0927\u094d\u092f\u093e\u0928 \u0926\u0947 \u0938\u0915\u0947\u0902\u0964"},
gc9(){return"\u0924\u093e\u0930 \u0935\u093e\u0926\u094d\u092f\u094b\u0902 \u0915\u093e \u0938\u092e\u0942\u0939 \u0917\u0930\u094d\u092e \u0930\u094b\u0936\u0928\u0940 \u0935\u093e\u0932\u0947 \u092e\u0902\u091a \u092a\u0930 \u092c\u091c\u093e \u0930\u0939\u093e \u0939\u0948\u0964 \u0939\u0930 \u0935\u093e\u0926\u0915 \u0915\u0947 \u0938\u094d\u0935\u0930\u0932\u093f\u092a\u093f \u0938\u094d\u091f\u0948\u0902\u0921 \u092a\u0930 \u091f\u0948\u092c\u0932\u0947\u091f \u092e\u0947\u0902 \u0905\u092a\u0928\u0940 \u0938\u094d\u0935\u0930\u0932\u093f\u092a\u093f \u0939\u0948\u0964"},
gcm(){return"\u092a\u0947\u0921\u0932 \u0938\u0947 \u092a\u0928\u094d\u0928\u093e \u092a\u0932\u091f\u0928\u093e"},
gcn(){return"\u0939\u093e\u0925 \u0938\u0902\u0917\u0940\u0924 \u092a\u0930\u0964\n\u092a\u0948\u0930 \u0905\u0917\u0932\u0947 \u092a\u0928\u094d\u0928\u0947 \u092a\u0930\u0964"},
gck(){return"\u0910\u0938\u093e \u0938\u0902\u0917\u0924 \u092a\u0928\u094d\u0928\u093e \u092a\u0932\u091f\u0928\u0947 \u0935\u093e\u0932\u093e \u092a\u0947\u0921\u0932 \u0907\u0938\u094d\u0924\u0947\u092e\u093e\u0932 \u0915\u0930\u0947\u0902 \u091c\u094b \u0915\u0940\u092c\u094b\u0930\u094d\u0921 \u0915\u092e\u093e\u0902\u0921 \u092d\u0947\u091c\u0924\u093e \u0939\u094b\u0964 \u0907\u0938\u0938\u0947 \u0935\u093e\u0926\u094d\u092f \u0938\u0947 \u0939\u093e\u0925 \u0939\u091f\u093e\u090f \u092c\u093f\u0928\u093e \u092a\u093f\u091b\u0932\u0947 \u092f\u093e \u0905\u0917\u0932\u0947 \u092a\u0928\u094d\u0928\u0947 \u092a\u0930 \u091c\u093e \u0938\u0915\u0924\u0947 \u0939\u0948\u0902\u0964"},
gcl(){return"\u092a\u0939\u0932\u0947 \u092a\u0947\u0921\u0932 \u0915\u094b \u0905\u092a\u0928\u0947 \u0909\u092a\u0915\u0930\u0923 \u0938\u0947 \u091c\u094b\u0921\u093c\u0947\u0902\u0964 \u0905\u0932\u0917-\u0905\u0932\u0917 \u092e\u0949\u0921\u0932 \u0915\u0940 \u0938\u0902\u0917\u0924\u0924\u093e \u0914\u0930 \u0935\u093e\u0938\u094d\u0924\u0935\u093f\u0915 \u0909\u092a\u0915\u0930\u0923\u094b\u0902 \u092a\u0930 \u0905\u0928\u0941\u092d\u0935 \u0905\u092d\u0940 \u091c\u093e\u0901\u091a\u093e \u091c\u093e \u0930\u0939\u093e \u0939\u0948\u0964"},
gcj(){return"\u090f\u0915 \u0938\u0947\u0932\u094b \u0935\u093e\u0926\u0915 \u0926\u094b\u0928\u094b\u0902 \u0939\u093e\u0925\u094b\u0902 \u0938\u0947 \u092c\u091c\u093e\u0924\u0947 \u0939\u0941\u090f \u0926\u093e\u090f\u0901 \u092a\u0948\u0930 \u0938\u0947 \u0926\u094b \u0938\u094d\u0935\u093f\u091a \u0935\u093e\u0932\u093e \u092a\u0928\u094d\u0928\u093e \u092a\u0932\u091f\u0928\u0947 \u0915\u093e \u092a\u0947\u0921\u0932 \u091a\u0932\u093e \u0930\u0939\u093e \u0939\u0948\u0964 \u0938\u094d\u091f\u0948\u0902\u0921 \u092a\u0930 \u091f\u0948\u092c\u0932\u0947\u091f \u0915\u0940 \u0938\u094d\u0935\u0930\u0932\u093f\u092a\u093f \u0926\u093f\u0916\u093e\u0908 \u0926\u0947 \u0930\u0939\u0940 \u0939\u0948\u0964"},
gcd(){return"AI \u0938\u0947 \u092c\u0928\u093e\u090f \u0917\u090f \u0909\u092a\u092f\u094b\u0917 \u0915\u0947 \u0909\u0926\u093e\u0939\u0930\u0923\u093e\u0924\u094d\u092e\u0915 \u091a\u093f\u0924\u094d\u0930; \u0910\u092a \u0915\u0947 \u0938\u094d\u0915\u094d\u0930\u0940\u0928\u0936\u0949\u091f \u092f\u093e \u0935\u093e\u0938\u094d\u0924\u0935\u093f\u0915 \u0917\u094d\u0930\u093e\u0939\u0915\u094b\u0902 \u0915\u0940 \u0915\u0939\u093e\u0928\u093f\u092f\u093e\u0901 \u0928\u0939\u0940\u0902\u0964"},
